hl.on("hyprland.start", function()
	hl.exec_cmd("$POLKIT_BIN")
	hl.exec_cmd("dbus-update-activation-environment --systemd --all")
	hl.exec_cmd("systemctl --user import-environment QT_QPA_PLATFORMTHEME WAYLAND_DISPLAY XDG_CURRENT_DESKTOP")
	hl.exec_cmd("awww-daemon")
	hl.exec_cmd("avizo-service")
	hl.exec_cmd("~/.config/hypr/scripts/awww-random.sh ~/wallpapers/")
	hl.exec_cmd("sleep 5; waybar -c ~/.config/waybar/config -s ~/.config/waybar/style.css")
	hl.exec_cmd("sleep 6; blueman-applet")
	hl.exec_cmd("nm-applet --indicator")
	hl.exec_cmd("hypridle")
	hl.exec_cmd("sleep 12; mullvad-vpn")
	hl.exec_cmd("sleep 10; trayscale --hide-window")
end)
